        this.couponInputValue = '';
        this.couponError = '';
        this.isApplying = false;
        // Applied coupon codes rendered as removable chips below the input.
        // - Single-coupon (default): holds at most the one cart coupon.
        // - Multi-coupon (features::multi_coupon on): holds every applied code,
        //   sourced from the cart's `coupons` array so it survives a page refresh.
        this.appliedCoupons = [];
